## 3. `deploy.js` – Command Registration

```javascript
import { REST, Routes } from 'discord.js';
import { config } from 'dotenv';
import banCommand from './src/commands/ban.js';

config();

const rest = new REST({ version: '10' }).setToken(process.env.DISCORD_TOKEN);

(async () => {
  try {
    const commands = [banCommand.data.toJSON()];
    const guildId = process.env.GUILD_ID;

    if (guildId) {
      // Guild-specific registration (instant)
      await rest.put(
        Routes.applicationGuildCommands(process.env.CLIENT_ID, guildId),
        { body: commands }
      );
      console.log(`✅ Registered command in guild ${guildId}`);
    } else {
      // Global registration (can take up to 1 hour)
      await rest.put(
        Routes.applicationCommands(process.env.CLIENT_ID),
        { body: commands }
      );
      console.log('✅ Registered command globally');
    }
  } catch (error) {
    console.error('❌ Failed to register commands:', error);
  }
})();
```

