## 4. `src/commands/ban.js` – The `/ban` Command

```javascript
import {
  SlashCommandBuilder,
  PermissionFlagsBits,
  EmbedBuilder,
} from 'discord.js';

export default {
  data: new SlashCommandBuilder()
    .setName('ban')
    .setDescription('Ban a member from the server')
    .setDefaultMemberPermissions(PermissionFlagsBits.BanMembers)
    .addUserOption(option =>
      option.setName('target')
        .setDescription('The user to ban')
        .setRequired(true)
    )
    .addStringOption(option =>
      option.setName('reason')
        .setDescription('Reason for the ban')
        .setRequired(false)
    ),

  async execute(interaction) {
    // Defer reply to avoid timeouts
    await interaction.deferReply({ ephemeral: true });

    const targetUser = interaction.options.getUser('target');
    const reason = interaction.options.getString('reason') || 'No reason provided';

    // Self-ban protection
    if (targetUser.id === interaction.user.id) {
      return interaction.editReply('❌ You cannot ban yourself.');
    }

    // Fetch the guild member object
    const targetMember = await interaction.guild.members
      .fetch(targetUser.id)
      .catch(() => null);

    if (!targetMember) {
      return interaction.editReply('❌ That user is not in this server.');
    }

    // Hierarchy check: moderator must have a higher role
    if (
      targetMember.roles.highest.position >=
      interaction.member.roles.highest.position
    ) {
      return interaction.editReply(
        '❌ You cannot ban someone with an equal or higher role.'
      );
    }

    // Bot permission check
    if (!targetMember.bannable) {
      return interaction.editReply(
        '❌ I cannot ban that user. Check my role hierarchy and permissions.'
      );
    }

    // --- Forensic audit log (sent before the ban) ---
    const auditChannel = interaction.guild.channels.cache.get(
      process.env.AUDIT_LOG_CHANNEL_ID
    );

    if (auditChannel) {
      const forensicEmbed = new EmbedBuilder()
        .setTitle('🚨 Ban Executed')
        .setColor(0xff0000)
        .setThumbnail(targetUser.displayAvatarURL())
        .addFields(
          { name: 'Subject', value: `${targetUser.tag} (${targetUser.id})`, inline: true },
          { name: 'Moderator', value: `${interaction.user.tag}`, inline: true },
          { name: 'Reason', value: reason },
          { name: 'Timestamp', value: new Date().toLocaleString() }
        )
        .setFooter({ text: 'Forensic Data Captured' });

      await auditChannel.send({ embeds: [forensicEmbed] }).catch(() => {
        // If the audit channel is unreachable, log to console silently
        console.warn('Could not send audit log embed.');
      });
    }

    // Execute the ban
    try {
      await targetMember.ban({ reason });
      await interaction.editReply(
        `✅ ${targetUser.tag} has been banned. Reason: ${reason}`
      );
    } catch (error) {
      console.error('Ban error:', error);
      await interaction.editReply(
        '❌ An unexpected error occurred while banning the user.'
      );
    }
  },
};
```

**Key checks in order:**
1. **Self‑ban** – prevents moderators from banning themselves.  
2. **User in server** – avoids banning someone who already left.  
3. **Role hierarchy** – respects Discord’s rule that you cannot moderate users of equal or higher role.  
4. **Bot ability** – checks `targetMember.bannable` (combines bot permissions and hierarchy).  
5. **Forensic log** – sent *before* the ban to preserve evidence.  
6. **Ban execution** – with error handling.  

