#include <string>
#include <regex>
#include <sstream>
#include <cctype>

/**
 * Escape HTML special characters in a string.
 * This prevents injection of raw HTML and ensures safe rendering.
 */
static std::string html_escape(const std::string& s) {
    std::string out;
    out.reserve(s.size() * 2);
    for (char c : s) {
        switch (c) {
            case '&':  out.append("&amp;");  break;
            case '<':  out.append("&lt;");   break;
            case '>':  out.append("&gt;");   break;
            case '"':  out.append("&quot;"); break;
            case '\'': out.append("&#39;");  break;
            default:   out.push_back(c);     break;
        }
    }
    return out;
}

/**
 * Apply inline Markdown rules to a string that contains no block-level
 * structure (i.e., the content of a paragraph, list item, heading, etc.).
 * Order matters: bold before italic, code before emphasis to avoid
 * misinterpreting backticks.
 */
static std::string process_inline(const std::string& text) {
    std::string result = text;

    // Inline code (must be done before emphasis to protect backticks)
    static const std::regex code_re(R"(`([^`]+)`)");
    result = std::regex_replace(result, code_re, "<code>$1</code>");

    // Bold: **text** or __text__
    static const std::regex bold_re(R"(\*\*(.*?)\*\*|__(.*?)__)");
    result = std::regex_replace(result, bold_re, "<strong>$1$2</strong>");

    // Italic: *text* or _text_
    static const std::regex italic_re(R"(\*(.*?)\*|_(.*?)_)");
    result = std::regex_replace(result, italic_re, "<em>$1$2</em>");

    // Strikethrough: ~~text~~
    static const std::regex strike_re(R"(~~(.*?)~~)");
    result = std::regex_replace(result, strike_re, "<del>$1</del>");

    // Links: [text](url)
    static const std::regex link_re(R"(\[(.*?)\]\((.*?)\))");
    result = std::regex_replace(result, link_re, "<a href=\"$2\">$1</a>");

    return result;
}

/**
 * Convert a Markdown string to HTML.
 * Supports: headings (# to ######), bold, italic, strikethrough,
 * inline code, links, unordered lists (*, -, +), ordered lists (1.),
 * blockquotes (>), and paragraphs.
 *
 * This is a lightweight converter; it does not handle nested lists,
 * code fences, tables, or HTML passthrough.
 */
std::string markdown_to_html(const std::string& md) {
    std::istringstream stream(md);
    std::string line;
    std::string html;

    bool in_ul = false;      // inside an unordered list
    bool in_ol = false;      // inside an ordered list
    bool in_blockquote = false;
    bool in_paragraph = false;

    // Helper to close any open block-level container
    auto close_blocks = [&]() {
        if (in_ul)      { html += "</ul>\n"; in_ul = false; }
        if (in_ol)      { html += "</ol>\n"; in_ol = false; }
        if (in_blockquote) { html += "</blockquote>\n"; in_blockquote = false; }
        if (in_paragraph)  { html += "</p>\n"; in_paragraph = false; }
    };

    while (std::getline(stream, line)) {
        // Trim trailing carriage return (Windows line endings)
        if (!line.empty() && line.back() == '\r')
            line.pop_back();

        // Empty line: close all open blocks
        if (line.empty() || line.find_first_not_of(" \t") == std::string::npos) {
            close_blocks();
            continue;
        }

        std::smatch match;

        // ---- Blockquote ----
        if (std::regex_search(line, match, std::regex(R"(^>\s*(.*))"))) {
            close_blocks(); // blockquote is a separate block
            html += "<blockquote>\n";
            html += "  " + process_inline(html_escape(match[1].str())) + "\n";
            html += "</blockquote>\n";
            continue;
        }

        // ---- Heading ----
        static const std::regex heading_re(R"(^(#{1,6})\s+(.*))");
        if (std::regex_search(line, match, heading_re)) {
            close_blocks();
            int level = match[1].length();
            std::string title = process_inline(html_escape(match[2].str()));
            html += "<h" + std::to_string(level) + ">" + title +
                    "</h" + std::to_string(level) + ">\n";
            continue;
        }

        // ---- Unordered list item ----
        static const std::regex ul_re(R"(^\s*[\*\-\+]\s+(.*))");
        if (std::regex_search(line, match, ul_re)) {
            if (!in_ul) {
                close_blocks();
                html += "<ul>\n";
                in_ul = true;
            }
            html += "  <li>" + process_inline(html_escape(match[1].str())) + "</li>\n";
            continue;
        }

        // ---- Ordered list item ----
        static const std::regex ol_re(R"(^\s*(\d+)\.\s+(.*))");
        if (std::regex_search(line, match, ol_re)) {
            if (!in_ol) {
                close_blocks();
                html += "<ol>\n";
                in_ol = true;
            }
            html += "  <li>" + process_inline(html_escape(match[2].str())) + "</li>\n";
            continue;
        }

        // ---- Paragraph (default) ----
        if (!in_paragraph) {
            close_blocks();
            html += "<p>";
            in_paragraph = true;
        } else {
            html += "\n"; // line break inside paragraph
        }
        html += process_inline(html_escape(line));
    }

    // Close any remaining open blocks at end of input
    close_blocks();

    return html;
}
```

**Design notes**

- **Safety first**: All text content is HTML‑escaped before inline processing. This prevents accidental HTML injection and ensures angle brackets, ampersands, etc. are displayed correctly.
- **Line‑by‑line state machine**: The function reads the Markdown one line at a time, tracking whether we are inside a list, blockquote, or paragraph. Empty lines reset the state, which is the standard Markdown convention for separating blocks.
- **Inline pipeline**: `process_inline` applies regex replacements in a fixed order: code first (to protect backticks), then bold, italic, strikethrough, and links. This avoids the “double

# Complete Snake Game in C with Smooth Animation and Bitmap Graphics

Below is a fully functional Snake game written in C using SDL2. It features smooth, interpolated movement and renders the entire level using bitmap images loaded from a sprite sheet.

## Architecture Overview

The game uses a **fixed-timestep logic loop** with **variable-rate rendering** — the key to smooth motion. The snake's logical position updates at 10 Hz, but the renderer interpolates between positions at your monitor's refresh rate (60+ Hz), creating fluid movement instead of grid-snapping.

