```javascript
/**
 * Prints the first prime number found in an array of exactly 5 numbers.
 * If no prime exists, nothing is printed (intentionally silent).
 *
 * @param {Array} arr - An array of exactly 5 numbers.
 */
function printFirstPrime(arr) {
  // --- Strict length check (exactly 5) ---
  if (!Array.isArray(arr) || arr.length !== 5) {
    // In a production system you might throw or return a sentinel.
    // Here we silently exit to match the "no output" contract.
    return;
  }

  // --- Efficient primality test (6k ± 1 optimisation) ---
  const isPrime = (n) => {
    if (!Number.isInteger(n) || n < 2) return false;
    if (n === 2 || n === 3) return true;
    if (n % 2 === 0 || n % 3 === 0) return false;
    // Check only candidates of the form 6k ± 1 up to sqrt(n)
    for (let i = 5; i * i <= n; i += 6) {
      if (n % i === 0 || n % (i + 2) === 0) return false;
    }
    return true;
  };

  // --- Find and print the first prime ---
  const firstPrime = arr.find(isPrime);
  if (firstPrime !== undefined) {
    console.log(firstPrime);
  }
  // No output if undefined (no prime among the five numbers)
}
```

